1: import { useCallback, useEffect, useState } from 'react';
2: import { RefreshCw, Settings2, Sparkles } from 'lucide-react';
3: import {
4:   dayTitle, greetingFor, isStatusTab, STATUS_TAB_PREFERENCE, zonedDay, zonedHour, type StatusTab,
5: } from '../../../features/review/statusPresentation';
6: import { readPreference, writePreference } from '../../../services/desktopPreferences';
7: import { fetchMemoryStatus } from '../../../services/experienceMemoryService';
8: import { fetchProfileMaintenance } from '../../../services/personalContextService';
9: import { Button } from '../../common/Button';
10: import { LoadingTree } from '../../common/LoadingTree';
11: import { TopBar } from '../../common/TopBar';
12: import { TopBarAction } from '../../common/TopBarAction';
13: import { useLifeReview } from '../useLifeReview';
14: import { StatusInsightView } from './StatusInsightView';
15: import { StatusTabs } from './StatusTabs';
16: import { StatusTimelineView } from './StatusTimelineView';
17: import { StatusTodayView } from './StatusTodayView';
18: import styles from './LifeStatusPage.module.css';
19: 
20: interface LifeStatusPageProps {
21:   onOpenSettings?: (tab?: 'review' | 'context') => void;
22:   initialTab?: StatusTab;
23: }
24: 
25: /** 侧边栏「状态」一级工作台：以今天 / 认知 / 足迹三分段展示每日复盘、目标、节律、四维认知与联系足迹。 */
26: export function LifeStatusPage({ onOpenSettings, initialTab }: LifeStatusPageProps = {}) {
27:   const state = useLifeReview();
28:   const { settings: s, busy, act } = state;
29: 
30:   const [tab, setTab] = useState<StatusTab>(() => {
31:     if (initialTab) return initialTab;
32:     const saved = readPreference(STATUS_TAB_PREFERENCE);
33:     return isStatusTab(saved) ? saved : 'today';
34:   });
35:   const [memorySummary, setMemorySummary] = useState<{ active: number; total: number } | null>(null);
36:   const [hasProposal, setHasProposal] = useState(false);
37: 
38:   const loadAuxStatus = useCallback(async () => {
39:     const [mem, maint] = await Promise.all([
40:       fetchMemoryStatus()
41:         .then(res => (res && typeof res.sourceTotal === 'number' && typeof res.sourceActive === 'number'
42:           ? { active: res.sourceActive, total: res.sourceTotal }
43:           : null))
44:         .catch(() => null),
45:       fetchProfileMaintenance()
46:         .then(res => Boolean(res && typeof res.lastResult === 'string' && res.pendingProposal))
47:         .catch(() => false),
48:     ]);
49:     setMemorySummary(mem);
50:     setHasProposal(maint);
51:   }, []);
52: 
53:   useEffect(() => {
54:     void loadAuxStatus();
55:   }, [loadAuxStatus]);
56: 
57:   function selectTab(next: StatusTab) {
58:     setTab(next);
59:     writePreference(STATUS_TAB_PREFERENCE, next);
60:   }
61: 
62:   async function refreshAll() {
63:     await Promise.all([state.load(), loadAuxStatus()]);
64:   }
65: 
66:   const timezone = s?.timezone || 'Asia/Shanghai';
67:   const today = zonedDay(timezone);
68:   const hour = zonedHour(timezone);
69:   const disabled = busy || state.dirty || !s?.enabled || !s.authorized;
70:   const reviewReady = Boolean(s?.enabled && s.authorized);
71: 
72:   return (
73:     <main className={styles.page}>
74:       <TopBar
75:         icon={<Sparkles size={19} />}
76:         title="状态"
77:         subtitle={`${dayTitle(today)} · ${greetingFor(hour)}`}
78:         actions={
79:           <div className={styles.headerActions}>
80:             <TopBarAction variant="ghost" icon={<RefreshCw size={14} />} disabled={busy || state.loading}
81:               title="刷新状态数据" onClick={() => void refreshAll()}>
82:               {state.loading ? '读取中…' : '刷新'}
83:             </TopBarAction>
84:             {onOpenSettings && (
85:               <>
86:                 <TopBarAction variant="ghost" title="个人上下文设置" onClick={() => onOpenSettings('context')}>上下文</TopBarAction>
87:                 <TopBarAction variant="ghost" iconOnly aria-label="生活复盘设置" icon={<Settings2 size={18} />}
88:                   onClick={() => onOpenSettings('review')}>
89:                   <span className={styles.visuallyHidden}>生活复盘设置</span>
90:                 </TopBarAction>
91:               </>
92:             )}
93:           </div>
94:         }
95:       />
96: 
97:       <div className={styles.workspace}>
98:         <div className={styles.content}>
99:           <div className={styles.contentInner}>
100:             {state.loading && !s && (
101:               <div className={styles.loadingCenter}>
102:                 <LoadingTree size="large" label="正在读取个人状态与复盘…" />
103:               </div>
104:             )}
105: 
106:             {state.error && (
107:               <p role="alert" className={styles.error}>
108:                 <span>{state.error}</span>
109:                 <Button size="sm" onClick={() => void refreshAll()}>重新读取</Button>
110:               </p>
111:             )}
112: 
113:             {s && (
114:               <>
115:                 <div className={styles.toolbar}>
116:                   <StatusTabs value={tab} onChange={selectTab} />
117:                   <div className={styles.pills} aria-label="状态摘要">
118:                     {reviewReady ? (
119:                       <span className={styles.quietStat} data-state="on"><i aria-hidden="true" />复盘已授权</span>
120:                     ) : (
121:                       <button type="button" className={styles.pillBtn} data-tone="warn"
122:                         disabled={!onOpenSettings} onClick={() => onOpenSettings?.('review')}>
123:                         <i aria-hidden="true" />{!s.enabled ? '复盘未启用 · 去设置' : '复盘未授权 · 去开启'}
124:                       </button>
125:                     )}
126: 
127:                     {state.companion && (
128:                       <button type="button" className={styles.quietBtn} data-state={state.companion.companionEnabled ? 'on' : 'off'}
129:                         onClick={() => selectTab('today')}>
130:                         <i aria-hidden="true" />{state.companion.companionEnabled ? '陪伴中' : '陪伴未开启'}
131:                       </button>
132:                     )}
133: 
134:                     {hasProposal && (
135:                       <button type="button" className={styles.pillBtn} data-tone="warn" onClick={() => selectTab('insight')}>
136:                         <i aria-hidden="true" />待确认画像建议
137:                       </button>
138:                     )}
139: 
140:                     {memorySummary && (
141:                       <button type="button" className={styles.quietBtn} onClick={() => selectTab('insight')}>
142:                         经历来源 {memorySummary.total}
143:                       </button>
144:                     )}
145:                   </div>
146:                 </div>
147: 
148:                 {tab === 'today' && (
149:                   <StatusTodayView settings={s} companion={state.companion} history={state.history}
150:                     habit={state.habit} suggestion={state.habitSuggestion} today={today}
151:                     busy={busy} generating={state.generating} disabled={disabled} act={act} onOpenSettings={onOpenSettings} />
152:                 )}
153: 
154:                 {tab === 'insight' && (
155:                   <StatusInsightView companion={state.companion} timezone={timezone} busy={busy}
156:                     memorySummary={memorySummary} onPendingProposalChange={setHasProposal} act={act} />
157:                 )}
158: 
159:                 {tab === 'timeline' && (
160:                   <StatusTimelineView settings={s} history={state.history} candidates={state.candidates}
161:                     nudges={state.nudges} archives={state.archives} busy={busy} disabled={disabled} act={act} />
162:                 )}
163:               </>
164:             )}
165:           </div>
166:         </div>
167:       </div>
168:     </main>
169:   );
170: }

