1: import { useState } from 'react';
2: import { CalendarCheck, ChevronDown, Info, RefreshCw, Sparkles } from 'lucide-react';
3: import { lifeReviewApi } from '../../../services/lifeReviewApi';
4: import type { LifeContent, LifeHabit, LifeSettings } from '../../../types/lifeReview';
5: import { lifeReviewTime } from '../../../features/review/lifeReviewPresentation';
6: import { dayTitle, formatDateTime, formatHour, sortVersions } from '../../../features/review/statusPresentation';
7: import { Button } from '../../common/Button';
8: import { ConfirmDialog } from '../../common/ConfirmDialog';
9: import { LifeContentCard } from '../LifeContentCard';
10: import { ReviewEmptyState } from '../ReviewEmptyState';
11: import { StatusCard } from './StatusCard';
12: import styles from './TodayReviewHero.module.css';
13: 
14: interface TodayReviewHeroProps {
15:   settings: LifeSettings;
16:   history: LifeContent[];
17:   habit: LifeHabit | null;
18:   today: string;
19:   busy: boolean;
20:   generating: boolean;
21:   disabled: boolean;
22:   act: (work: () => Promise<unknown>, message: string) => Promise<void>;
23:   onOpenSettings?: (tab?: 'review' | 'context') => void;
24: }
25: 
26: const BADGE_LABELS: Record<string, string> = {
27:   PENDING: '等待中', RUNNING: '生成中', READY: '已备好', DEGRADED: '未生成', SKIPPED: '未生成', UNKNOWN: '结果未知',
28: };
29: 
30: /** 今日复盘主卡：单层极简头部与阅读流；已有今日复盘时只提供单入口更新，避免与“准备”按钮冲突。 */
31: export function TodayReviewHero({ settings: s, history, habit, today, busy, generating, disabled, act, onOpenSettings }: TodayReviewHeroProps) {
32:   const [refreshOpen, setRefreshOpen] = useState(false);
33:   const [expandFailedPrev, setExpandFailedPrev] = useState(false);
34:   const ordered = sortVersions(history);
35:   const todayContent = ordered.find(c => c.day === today);
36:   const latest = ordered[0];
37:   const latestIsFailedPast = Boolean(!todayContent && latest && latest.items.length === 0 && latest.state !== 'PENDING' && latest.state !== 'RUNNING');
38:   const shown = todayContent ?? (latestIsFailedPast ? null : latest);
39:   const hour = habit?.active ? habit.availableHour : 21;
40:   const blocked = !s.enabled || !s.authorized;
41: 
42:   function prepare() {
43:     void act(() => lifeReviewApi.prepare(today, 0, false), '已开始后台生成今日复盘，请稍候…');
44:   }
45: 
46:   const shownZone = shown?.timezone || s.timezone;
47:   const badgeText = shown ? `v${shown.version} · ${BADGE_LABELS[shown.state] || shown.state}` : undefined;
48:   const badgeTone = shown?.state === 'READY' ? 'ready' : shown?.state === 'PENDING' || shown?.state === 'RUNNING' ? 'wait' : 'muted';
49:   const scheduleMeta = `每日 ${formatHour(hour)}${s.feishu ? ' · 飞书同步' : ''}`;
50:   const description = shown ? (
51:     <span title={`资料截至 ${lifeReviewTime(shown.sourceAsOf, shownZone)}（${shownZone}）`}>
52:       截至 {formatDateTime(shown.sourceAsOf, shownZone)} · {scheduleMeta}
53:     </span>
54:   ) : scheduleMeta;
55: 
56:   const primaryAction = generating ? (
57:     <Button size="sm" variant="outline" icon={<Sparkles size={14} />} disabled>正在生成复盘…</Button>
58:   ) : todayContent ? (
59:     <Button size="sm" variant="outline" icon={<RefreshCw size={13} />} disabled={disabled || todayContent.state === 'UNKNOWN'}
60:       onClick={() => setRefreshOpen(true)}>
61:       更新今天的复盘
62:     </Button>
63:   ) : (
64:     <Button size="sm" variant="primary" icon={<Sparkles size={14} />} disabled={disabled} onClick={prepare}>
65:       准备今天的复盘
66:     </Button>
67:   );
68: 
69:   return <StatusCard
70:     title={shown && !todayContent ? `${dayTitle(shown.day)} 复盘` : '今天的复盘'}
71:     tone="accent"
72:     variant="card"
73:     className={styles.heroCard}
74:     icon={<CalendarCheck size={17} />}
75:     badge={badgeText ? <span className={styles.versionBadge} data-tone={badgeTone}>{badgeText}</span> : undefined}
76:     description={description}
77:     actions={primaryAction}
78:   >
79:     {blocked && (
80:       <div className={styles.notice} role="note">
81:         <Info size={16} aria-hidden="true" />
82:         <div>
83:           <strong>{!s.enabled ? '生活复盘尚未启用' : '生活复盘尚未完成用途授权'}</strong>
84:           <p>授权读取范围与模型后即可使用。</p>
85:         </div>
86:         {onOpenSettings && <Button size="sm" variant="outline" onClick={() => onOpenSettings('review')}>前往复盘设置</Button>}
87:       </div>
88:     )}
89: 
90:     {!shown && (
91:       <ReviewEmptyState
92:         title={latest ? '今天还没有复盘' : '还没有生活复盘'}
93:         description={`每天 ${formatHour(hour)} 自动生成，也可以现在手动准备。`}
94:       />
