24: /** 按后端配置时区计算归属日，避免用本机日期推断。 */
25: export function zonedDay(timezone: string, now = new Date()): string {
26:   let parts: Intl.DateTimeFormatPart[];
27:   try {
28:     parts = new Intl.DateTimeFormat('en', { timeZone: timezone || 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(now);
29:   } catch {
30:     parts = new Intl.DateTimeFormat('en', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(now);
31:   }
32:   return ['year', 'month', 'day'].map(type => parts.find(part => part.type === type)?.value || '').join('-');
33: }
