35: /** 返回配置时区下的当前时分、时间文案及 24 小时进度比例（0–1），避免依赖本机时区。 */
36: export function zonedClock(timezone: string, now = new Date()): { hour: number; minute: number; label: string; fraction: number } {
37:   let parts: Intl.DateTimeFormatPart[] = [];
38:   try {
39:     parts = new Intl.DateTimeFormat('en', { timeZone: timezone || 'Asia/Shanghai', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(now);
40:   } catch {
41:     try {
42:       parts = new Intl.DateTimeFormat('en', { timeZone: 'Asia/Shanghai', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(now);
43:     } catch { /* fall back to local Date */ }
44:   }
45:   const h = Number(parts.find(p => p.type === 'hour')?.value);
46:   const m = Number(parts.find(p => p.type === 'minute')?.value);
47:   const hour = Number.isFinite(h) ? h % 24 : now.getHours();
48:   const minute = Number.isFinite(m) ? m % 60 : now.getMinutes();
49:   return {
50:     hour,
51:     minute,
52:     label: `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`,
53:     fraction: Math.min(0.99, Math.max(0.01, (hour + minute / 60) / 24)),
54:   };
55: }
