162:     return {
163:       key: `nudge-${n.id}`, id: n.id, source: 'nudge', category: n.kind === 'IDLE_CHECKIN' ? 'greeting' : 'alert',
164:       title, text: cleanOutreachText(n.text, title), state: n.state, stateLabel: NUDGE_STATES[n.state] || n.state,
165:       at: n.sentAt || n.createdAt, feedback: n.feedback || '',
166:     };
167:   });
168:   const candidateEntries: OutreachEntry[] = candidates.map(c => ({
169:     key: `candidate-${c.id}`, id: c.id, source: 'candidate', category: 'candidate',
170:     title: c.topic.startsWith('review-') ? `${c.topic.slice(7)} 生活复盘` : c.topic,
171:     text: c.state === 'PENDING' ? '有值得呈现的新信息，等待合适时机呈现。' : '复盘候选记录，未回复不会被判为失败。',
172:     state: c.state, stateLabel: CANDIDATE_STATES[c.state] || c.state, at: c.dueAt, feedback: c.feedback || '',
