189: /** 忙碌窗口支持跨零点（例如 22—6）。 */
190: export function isBusyHour(hour: number, start: number, end: number): boolean {
191:   if (start === end) return false;
192:   return start < end ? hour >= start && hour < end : hour >= start || hour < end;
193: }
