195: export interface RhythmBar { hour: number; count: number; ratio: number; busy: boolean }
196: 
197: export function rhythmBars(hourCounts: number[] | undefined, busyStart?: number, busyEnd?: number): RhythmBar[] {
198:   const counts = Array.from({ length: 24 }, (_, hour) => Math.max(0, Number(hourCounts?.[hour]) || 0));
199:   const max = Math.max(...counts, 0);
200:   return counts.map((count, hour) => ({
201:     hour, count, ratio: max > 0 ? count / max : 0,
202:     busy: busyStart !== undefined && busyEnd !== undefined && isBusyHour(hour, busyStart, busyEnd),
203:   }));
204: }
