235: export function companionPulse(enabled: boolean, rhythm: LifeRhythmState, cognition: LifeCognition, timezone: string): { tone: 'off' | 'wait' | 'on'; text: string } {
236:   if (!enabled) return { tone: 'off', text: '主动陪伴未开启' };
237:   if (rhythm.busyDeferred) return { tone: 'wait', text: `忙时免打扰顺延中（${formatHour(cognition.busyStartHour)}—${formatHour(cognition.busyEndHour)}）` };
238:   if (rhythm.unansweredCount > 0) return { tone: 'wait', text: `连续 ${rhythm.unansweredCount} 次未回，已拉长跟进间隔` };
239:   if (rhythm.nextReachAt) return { tone: 'on', text: `下次问候预计 ${formatDateTime(rhythm.nextReachAt, timezone)}` };
240:   return { tone: 'on', text: '正在安排合适问候时机' };
