4: import { Drawer } from '../common/Drawer';
5: import { Button } from '../common/Button';
6: import { ReviewDisclosure } from './ReviewDisclosure';
7: import styles from './LifeReviewDetails.module.css';
8: 
9: interface Props { content: LifeContent; timezone: string; mode: 'references' | 'version'; onClose: () => void }
10: 
11: /** 同一版本的只读材料与版本详情内容，支持在独立抽屉和按日抽屉内复用。 */
12: export function LifeReviewDetailsContent({ content: c, timezone, mode }: Omit<Props, 'onClose'>) {
13:   const [category, setCategory] = useState('ALL');
14:   const groups = lifeReferenceGroups(c);
15:   const count = groups.reduce((total, group) => total + group.entries.length, 0);
16:   const zone = c.timezone || timezone;
17:   const time = (value: string) => lifeReviewTime(value, zone);
18:   return <div className={styles.body}>
19:       {mode === 'references' ? <>
20:         <p className={styles.note}>这是本版实际读取的材料快照，不是完整聊天记录，也不会自动追加新消息。材料不等于已确认事实。</p>
21:         <dl className={styles.metadata}>
22:           <div><dt>近期原文范围</dt><dd>{lifeReviewWindow(c.coverage)}</dd></div>
23:           <div><dt>资料截止</dt><dd>{time(c.sourceAsOf)}（{zone}）</dd></div>
24:         </dl>
25:         <p className={styles.note}>聊天仅取部分普通会话中的用户原文；条数和字数有限。财务、学习及待办为归属日数值；目标可能早于近期窗口。</p>
26:         <nav className={styles.filters} aria-label="参考记录分类">
27:           <Button size="sm" variant={category === 'ALL' ? 'secondary' : 'ghost'} aria-pressed={category === 'ALL'} onClick={() => setCategory('ALL')}>全部 · {count}</Button>
28:           {groups.map(group => <Button key={group.key} size="sm" variant={category === group.key ? 'secondary' : 'ghost'}
29:             aria-pressed={category === group.key} onClick={() => setCategory(group.key)}>{group.title} · {group.entries.length}</Button>)}
30:         </nav>
31:         {count === 0 && <p className={styles.empty}>此版本没有保存参考记录，不代表当天没有发生其他事情。</p>}
32:         {groups.filter(g => category === 'ALL' || category === g.key).map(group => <section key={group.key} aria-label={group.title} className={styles.group}>
33:           <h3>{group.title}<span>{group.entries.length} 条</span></h3>
34:           {group.entries.map(entry => <article className={styles.entry} key={entry.id}>
35:             <p className={styles.date}>{time(entry.time)}</p><p>{entry.text}</p>
36:             {entry.truncated && <p className={styles.note}>仅展示本版读取的片段，原文未完整读取。</p>}
37:           </article>)}
38:         </section>)}
39:       </> : <>
40:         <dl className={styles.metadata}>
41:           <div><dt>复盘归属日</dt><dd>{c.day} · 第{c.version}版</dd></div>
42:           <div><dt>近期原文范围</dt><dd>{lifeReviewWindow(c.coverage)}</dd></div>
43:           <div><dt>资料截止</dt><dd>{time(c.sourceAsOf)}</dd></div>
44:           <div><dt>最早可主动呈现</dt><dd>{time(c.availableAt)}</dd></div>
45:           <div><dt>时区</dt><dd>{zone}</dd></div>
46:           <div><dt>固定模型</dt><dd>{c.modelName || '未记录'}</dd></div>
47:           <div><dt>已读取材料</dt><dd>{groups.map(g => `${g.title} ${g.entries.length} 条`).join('、') || '无参考记录'}</dd></div>
48:         </dl>
49:         <p className={styles.note}>呈现时间是最早允许主动联系的时间，不代表已经发送或已读。补充经历会创建新版本，原版本及已发送副本保留。</p>
50:         {c.message && <section className={styles.group}><h3>本次处理说明</h3><p>{c.message}</p></section>}
51:         <ReviewDisclosure title="技术排查详情" description="仅在排查问题时使用，包含读取限制和内部来源编号。">
52:           <p className={styles.note}>模型连接编号：{c.providerId || '未记录'}</p>
53:           <p className={styles.raw}>{c.coverage || '此版本未记录详细读取说明'}</p>
