7: export interface ConfirmDialogProps {
8:   /** 弹框显隐 */
9:   open: boolean;
10:   /** 弹框标题 */
11:   title: string;
12:   /** 语气/类型：'warning'（默认，橙黄预警）| 'danger'（红色危险操作）| 'info'（蓝色通知） */
13:   tone?: 'warning' | 'danger' | 'info';
14:   /** 自定义标题栏图标（未提供则按 tone 自动展示） */
15:   icon?: React.ReactNode;
16:   /** 描述文案（简单提示直接使用该属性） */
17:   description?: React.ReactNode;
18:   /** 复杂主体内容（若有结构化内容直接传入 children） */
19:   children?: React.ReactNode;
20:   /** 取消按钮文字，默认 '取消' */
21:   cancelText?: string;
22:   /** 确认按钮文字，默认 '确认' */
23:   confirmText?: string;
24:   /** 确认按钮变体：默认 tone==='danger' 时为 'danger'，其余为 'primary' */
25:   confirmVariant?: 'primary' | 'danger' | 'outline';
26:   /** 是否展示取消按钮，默认 true */
27:   showCancel?: boolean;
28:   /** 是否处于处理中/禁用状态 */
29:   busy?: boolean;
30:   /** 弹框宽度，默认 420px */
31:   width?: number | string;
32:   /** 取消/关闭回调 */
33:   onClose: () => void;
34:   /** 确认回调 */
35:   onConfirm: () => void | Promise<void>;
36: }
37: 
38: export const ConfirmDialog: React.FC<ConfirmDialogProps> = ({
39:   open,
40:   title,
41:   tone = 'warning',
42:   icon,
43:   description,
44:   children,
45:   cancelText = '取消',
46:   confirmText = '确认',
47:   confirmVariant,
48:   showCancel = true,
49:   busy = false,
50:   width = 420,
51:   onClose,
52:   onConfirm,
53: }) => {
54:   if (!open) return null;
55: 
56:   const defaultIcon =
57:     tone === 'danger' ? (
58:       <AlertCircle size={16} strokeWidth={2.2} />
59:     ) : tone === 'info' ? (
60:       <Info size={16} strokeWidth={2.2} />
61:     ) : (
62:       <AlertTriangle size={16} strokeWidth={2.2} />
63:     );
64: 
65:   const headerIcon = (
66:     <div className={`${styles.iconBadge} ${styles[tone]}`}>
67:       {icon ?? defaultIcon}
68:     </div>
69:   );
70: 
71:   const resolvedConfirmVariant =
72:     confirmVariant ?? (tone === 'danger' ? 'danger' : 'primary');
73: 
74:   return (
75:     <Modal
76:       open={open}
77:       title={title}
78:       icon={headerIcon}
79:       width={width}
80:       centered
81:       busy={busy}
82:       onClose={() => {
83:         if (!busy) onClose();
84:       }}
85:     >
86:       <div className={styles.container}>
87:         <div className={styles.body}>
88:           {description && <div className={styles.description}>{description}</div>}
89:           {children}
90:         </div>
91:         <div className={styles.actions}>
92:           {showCancel && (
93:             <Button
94:               type="button"
95:               variant="outline"
96:               size="md"
97:               disabled={busy}
98:               onClick={onClose}
99:             >
100:               {cancelText}
101:             </Button>
102:           )}
103:           <Button
104:             type="button"
105:             variant={resolvedConfirmVariant}
106:             size="md"
107:             disabled={busy}
108:             onClick={onConfirm}
109:           >
110:             {busy ? '处理中…' : confirmText}
111:           </Button>
112:         </div>
113:       </div>
114:     </Modal>
115:   );
116: };

