.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-family: var(--font-sans);
  font-weight: 550;
  letter-spacing: -0.01em;
  border: 1px solid transparent;
  cursor: pointer;
  user-select: none;
  transition: background-color 160ms ease, border-color 160ms ease, color 160ms ease, box-shadow 160ms ease, transform 140ms ease;
  white-space: nowrap;
}

.btn:disabled {
  opacity: 0.48;
  cursor: not-allowed;
  transform: none !important;
  box-shadow: none !important;
}

/* Sizes */
.sm {
  min-height: 30px;
  font-size: 12px;
  padding: 0 13px;
  border-radius: 999px;
}

.md {
  min-height: 36px;
  font-size: 13px;
  padding: 0 16px;
  border-radius: 999px;
}

.lg {
  min-height: 42px;
  font-size: 14px;
  font-weight: 600;
  padding: 0 22px;
  border-radius: 999px;
}

/* Variants */
.primary {
  background: linear-gradient(180deg, #1e293b 0%, #0f172a 100%);
  color: #ffffff;
  border-color: #0f172a;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.14), 0 1px 2px rgba(15, 23, 42, 0.12);
}

.primary:hover:not(:disabled) {
  background: linear-gradient(180deg, #334155 0%, #1e293b 100%);
  border-color: #1e293b;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.18), 0 4px 10px rgba(15, 23, 42, 0.14);
  transform: translateY(-0.5px);
}

.primary:active:not(:disabled) {
  background: #0f172a;
  border-color: #0f172a;
  transform: translateY(0) scale(0.985);
}

.primary:disabled {
  background: #e2e8f0;
  border-color: transparent;
  color: #94a3b8;
  opacity: 1;
}

.secondary {
  background-color: #f1f5f9;
  color: #1e293b;
  border-color: transparent;
}

.secondary:hover:not(:disabled) {
  background-color: #e2e8f0;
  color: #0f172a;
}

.secondary:active:not(:disabled) {
  transform: scale(0.985);
}

.outline {
  background-color: #f8fafc;
  color: #1e293b;
  border-color: rgba(15, 23, 42, 0.08);
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.03), inset 0 1px 0 #ffffff;
}

.outline:hover:not(:disabled) {
  background-color: #f1f5f9;
  border-color: rgba(15, 23, 42, 0.14);
  color: #0f172a;
  box-shadow: 0 2px 6px rgba(15, 23, 42, 0.05), inset 0 1px 0 #ffffff;
  transform: translateY(-0.5px);
}

.outline:active:not(:disabled) {
  transform: translateY(0) scale(0.985);
}

.ghost {
  background-color: transparent;
  color: #475569;
  border-color: transparent;
}

.ghost:hover:not(:disabled) {
  background-color: rgba(15, 23, 42, 0.045);
  color: #0f172a;
}

.danger {
  background: linear-gradient(180deg, #ef4444 0%, #dc2626 100%);
  color: #ffffff;
  border-color: #dc2626;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.16), 0 1px 2px rgba(220, 38, 38, 0.16);
}

.danger:hover:not(:disabled) {
  background: linear-gradient(180deg, #dc2626 0%, #b91c1c 100%);
  border-color: #b91c1c;
  transform: translateY(-0.5px);
}

/* 页面顶栏共用固定高度，避免各业务页覆盖按钮外观。 */
.toolbar {
  height: 30px;
