1: import { useEffect, useState } from 'react';
2: import { BrainCircuit, Database, FileText, PauseCircle } from 'lucide-react';
3: import {
4:   fetchPersonalContext, fetchProfileMaintenance, updatePersonalContextEnabled,
5: } from '../../services/personalContextService';
6: import type { PersonalContextSettings, ProfileMaintenanceStatus } from '../../types/personalContext';
7: import { Button } from '../common/Button';
8: import { LeverSwitch } from '../common/LeverSwitch';
9: import { useMessage } from '../common/Message';
10: import { formatTokenCount } from '../chat/tokenUsageFormat';
11: import { AgentResetSection } from '../reset/AgentResetSection';
12: import { ExperienceMemorySettings } from '../memory/ExperienceMemorySettings';
13: import { PersonalProfileSection } from './PersonalProfileSection';
14: import { SettingsPageLayout } from './SettingsPageLayout';
15: import styles from './PersonalContextSettingsPage.module.css';
16: 
17: /** 用户可控的稳定画像、相关记忆注入与辅助维护设置。 */
18: export function PersonalContextSettingsPage() {
19:   const { showMessage } = useMessage();
20:   const [settings, setSettings] = useState<PersonalContextSettings | null>(null);
21:   const [maintenance, setMaintenance] = useState<ProfileMaintenanceStatus | null>(null);
22:   const [loading, setLoading] = useState(true);
23:   const [saving, setSaving] = useState(false);
24:   const [error, setError] = useState<string | null>(null);
25: 
26:   const applyMaintenance = (next: ProfileMaintenanceStatus) => {
27:     setMaintenance(next);
28:     setSettings((current) => current ? { ...current, maintenanceEnabled: next.enabled } : current);
29:   };
30:   const load = async () => {
31:     setLoading(true);
32:     setError(null);
33:     try {
34:       const [context, maintenanceStatus] = await Promise.all([fetchPersonalContext(), fetchProfileMaintenance()]);
35:       setSettings(context);
36:       applyMaintenance(maintenanceStatus);
37:     } catch (cause) {
38:       setError(cause instanceof Error ? cause.message : '读取个人上下文失败');
39:     } finally {
40:       setLoading(false);
41:     }
42:   };
43:   useEffect(() => { void load(); }, []);
44: 
45:   const mutateSettings = async (operation: () => Promise<PersonalContextSettings>, success: string) => {
46:     setSaving(true); setError(null);
47:     try {
48:       setSettings(await operation());
49:       applyMaintenance(await fetchProfileMaintenance());
50:       showMessage('success', success);
51:     } catch (cause) {
52:       showMessage('error', cause instanceof Error ? cause.message : '保存个人上下文失败');
53:     } finally { setSaving(false); }
54:   };
55: 
56:   if (loading && !settings) return <SettingsPageLayout title="个人上下文" description="控制 Agent 自动了解你的方式。" loading loadingLabel="正在读取本地设置…"><div className={styles.state} /></SettingsPageLayout>;
57:   if (!settings || !maintenance) return <SettingsPageLayout title="个人上下文" description="控制 Agent 自动了解你的方式。"><div className={styles.state} role="alert"><p>{error}</p><Button variant="outline" onClick={() => void load()}>重新加载</Button></div></SettingsPageLayout>;
58: 
59:   return <SettingsPageLayout title="个人上下文" description="管理 Agent 对你的了解和记忆。">
60:     <div className={styles.content}>
61:       <section className={styles.switchRow} aria-labelledby="context-switch-title">
62:         <div className={styles.switchCopy}><span className={styles.icon}><BrainCircuit size={18} aria-hidden="true" /></span><div><h2 id="context-switch-title">自动使用个人上下文</h2><p>{settings.enabled ? '回答时参考你的个人信息和相关经历。' : '已暂停使用，已有个人信息和记忆不会删除。'}</p></div></div>
63:         <LeverSwitch checked={settings.enabled} disabled={saving} label={settings.enabled ? '已开启' : '已暂停'} onChange={(enabled) => void mutateSettings(() => updatePersonalContextEnabled(enabled), enabled ? '已开启个人上下文' : '已暂停个人上下文')} />
64:       </section>
65: 
66:       <dl className={styles.budgets} aria-label="单次调用 Token 硬预算">
67:         <div><dt><FileText size={14} />个人画像</dt><dd>≤ {formatTokenCount(settings.profileTokenBudget)}</dd></div>
68:         <div><dt><Database size={14} />相关记忆</dt><dd>≤ {formatTokenCount(settings.memoryTokenBudget)}</dd></div>
69:         <div><dt><PauseCircle size={14} />合计上限</dt><dd>≤ {formatTokenCount(settings.totalTokenBudget)}</dd></div>
70:       </dl>
71: 
72:       <PersonalProfileSection
73:         settings={settings}
74:         maintenance={maintenance}
75:         saving={saving}
76:         showMaintenanceToggle
77:         onSettingsChange={setSettings}
78:         onMaintenanceChange={applyMaintenance}
79:       />
80: 
81:       <ExperienceMemorySettings />
82:       <AgentResetSection />
83:       <p className={styles.privacy}>个人信息和更新建议保存在本机，暂停使用不会删除。</p>
84:     </div>
85:   </SettingsPageLayout>;
86: }
